def transform(g):
    import copy
    g=[row[:] for row in g]
    h,w=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    # find colors
    colors=[c for c in cnt if c!=bg]
    # blocks: connected components size>1 ; markers: single cells
    seen=[[False]*w for _ in range(h)]
    comps=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and not seen[i][j]:
                stack=[(i,j)];seen[i][j]=True;comp=[]
                while stack:
                    a,b=stack.pop();comp.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and not seen[na][nb] and g[na][nb]==g[i][j]:
                            seen[na][nb]=True;stack.append((na,nb))
                comps.append((g[i][j],comp))
    marker_colors={c for c,comp in comps if len(comp)==1}
    out=[row[:] for row in g]
    for c,comp in comps:
        if len(comp)==1:
            i,j=comp[0]
            out[i][j]=4
            for r in range(i+1,h):
                if g[r][j]!=bg: break
                out[r][j]=c
        else:
            # topmost block: extend down
            top=min(a for a,b in comp)
            if top==0:
                cols=sorted({b for a,b in comp})
                for j in cols:
                    for r in range(1,h):
                        if g[r][j]!=bg: break
                        out[r][j]=next(iter(marker_colors)) if marker_colors else c
    return out

